static bool env_enabled(const char *name) {
    const char *value = getenv(name);
    return value && value[0] && strcmp(value, "0") != 0 &&
           strcasecmp(value, "false") != 0 && strcasecmp(value, "no") != 0;
}

static bool env_disabled(const char *name) {
    return env_enabled(name);
}

static bool env_truthy_default(const char *name, bool default_value) {
    const char *value = getenv(name);
    if (!value || !value[0]) return default_value;
    if (strcmp(value, "0") == 0 || strcasecmp(value, "false") == 0 ||
        strcasecmp(value, "no") == 0) {
        return false;
    }
    return true;
}

static bool vulkan_v5_object_transport_enabled(void) {
    /*
     * Image, image-view, and sampler handles are part of the Vulkan object
     * graph.  Treat V5 object transport as the default correctness path, while
     * keeping a deliberate kill switch for device triage.
     */
    return env_truthy_default("PDOCKER_VULKAN_ENABLE_V5_OBJECT_TRANSPORT", true) &&
           !env_truthy_default("PDOCKER_VULKAN_DISABLE_V5_OBJECT_TRANSPORT", false);
}

static uint64_t next_vulkan_object_generation(void) {
    return __sync_add_and_fetch(&g_vulkan_object_generation, 1);
}

static void ensure_vulkan_dispatchable_object_ids(void) {
    static int initialized;
    if (__sync_lock_test_and_set(&initialized, 1)) return;
    g_device.object_id = next_vulkan_object_generation();
    if (g_device.instance_object_id == 0) {
        g_device.instance_object_id = next_vulkan_object_generation();
    }
    g_queue.object_id = next_vulkan_object_generation();
}

static void instance_register(PdockerVkInstance *instance) {
    if (!instance) return;
    instance->next = g_instances;
    g_instances = instance;
}

static PdockerVkInstance *instance_unregister(VkInstance instance) {
    PdockerVkInstance *target = (PdockerVkInstance *)instance;
    if (!target) return NULL;
    PdockerVkInstance **link = &g_instances;
    while (*link) {
        if (*link == target) {
            *link = target->next;
            target->next = NULL;
            return target;
        }
        link = &(*link)->next;
    }
    return NULL;
}

static bool instance_handle_resolve(VkInstance instance, PdockerVkInstance **out_instance) {
    PdockerVkInstance *target = (PdockerVkInstance *)instance;
    if (out_instance) *out_instance = NULL;
    if (!target) return false;
    for (PdockerVkInstance *candidate = g_instances; candidate; candidate = candidate->next) {
        if (candidate == target) {
            if (out_instance) *out_instance = candidate;
            return true;
        }
    }
    return false;
}

static bool instance_handle_object_id(VkInstance instance, uint64_t *out_object_id) {
    PdockerVkInstance *pdocker_instance = NULL;
    if (out_object_id) *out_object_id = 0;
    if (instance == VK_NULL_HANDLE) return true;
    if (!instance_handle_resolve(instance, &pdocker_instance)) return false;
    if (!pdocker_instance || pdocker_instance->object_id == 0) return false;
    if (out_object_id) *out_object_id = pdocker_instance->object_id;
    return true;
}

static bool physical_device_handle_resolve(
        VkPhysicalDevice physicalDevice,
        PdockerVkPhysicalDevice **out_physical_device) {
    PdockerVkPhysicalDevice *target = (PdockerVkPhysicalDevice *)physicalDevice;
    if (out_physical_device) *out_physical_device = NULL;
    if (!target) return false;
    if (target == &g_device) {
        ensure_vulkan_dispatchable_object_ids();
        if (out_physical_device) *out_physical_device = &g_device;
        return true;
    }
    for (PdockerVkPhysicalDevice *candidate = g_physical_devices;
         candidate;
         candidate = candidate->next) {
        if (candidate == target) {
            if (out_physical_device) *out_physical_device = candidate;
            return true;
        }
    }
    return false;
}

static PdockerVkPhysicalDevice *physical_device_for_instance(
        const PdockerVkInstance *instance) {
    if (!instance || instance->object_id == 0) {
        ensure_vulkan_dispatchable_object_ids();
        return &g_device;
    }
    for (PdockerVkPhysicalDevice *candidate = g_physical_devices;
         candidate;
         candidate = candidate->next) {
        if (candidate->instance_object_id == instance->object_id) return candidate;
    }
    PdockerVkPhysicalDevice *physical = calloc(1, sizeof(*physical));
    if (!physical) return NULL;
    physical->object_id = next_vulkan_object_generation();
    physical->instance_object_id = instance->object_id;
    set_loader_magic_value(physical);
    physical->next = g_physical_devices;
    g_physical_devices = physical;
    return physical;
}

static void physical_devices_unregister_for_instance(uint64_t instance_object_id) {
    if (instance_object_id == 0) return;
    PdockerVkPhysicalDevice **link = &g_physical_devices;
    while (*link) {
        PdockerVkPhysicalDevice *physical = *link;
        if (physical->instance_object_id == instance_object_id) {
            *link = physical->next;
            free(physical);
        } else {
            link = &physical->next;
        }
    }
}

