static bool device_handle_object_id(VkDevice device, uint64_t *out_object_id) {
    PdockerVkDevice *pdocker_device = NULL;
    if (out_object_id) *out_object_id = 0;
    if (!device_handle_resolve(device, &pdocker_device)) return false;
    if (!pdocker_device || pdocker_device->object_id == 0) return false;
    if (out_object_id) *out_object_id = pdocker_device->object_id;
    return true;
}

static uint64_t device_owner_id_or_zero(VkDevice device) __attribute__((unused));
static uint64_t device_owner_id_or_zero(VkDevice device) {
    uint64_t object_id = 0;
    (void)device_handle_object_id(device, &object_id);
    return object_id;
}

static bool device_owner_id_or_zero_checked(VkDevice device, uint64_t *out_object_id) {
    if (out_object_id) *out_object_id = 0;
    if (device == VK_NULL_HANDLE) return true;
    return device_handle_object_id(device, out_object_id);
}

static bool device_owner_matches_or_unowned(VkDevice device, uint64_t owner_device_id) {
    if (owner_device_id == 0) return device == VK_NULL_HANDLE;
    uint64_t object_id = 0;
    return device_handle_object_id(device, &object_id) && object_id == owner_device_id;
}

static bool queue_owner_matches_or_unowned(const PdockerVkQueue *queue, uint64_t owner_device_id) {
    if (owner_device_id == 0) return !queue || queue->device_object_id == 0;
    return queue && queue->device_object_id != 0 && queue->device_object_id == owner_device_id;
}

static bool owner_device_ids_match_or_unowned(uint64_t lhs_owner_device_id, uint64_t rhs_owner_device_id) {
    return lhs_owner_device_id == rhs_owner_device_id;
}

static bool physical_device_instance_object_id(
        VkPhysicalDevice physicalDevice,
        uint64_t *out_instance_object_id) {
    PdockerVkPhysicalDevice *physical = NULL;
    if (out_instance_object_id) *out_instance_object_id = 0;
    if (physicalDevice == VK_NULL_HANDLE) return true;
    if (!physical_device_handle_resolve(physicalDevice, &physical)) return false;
    if (!physical || physical->instance_object_id == 0) return false;
    if (out_instance_object_id) *out_instance_object_id = physical->instance_object_id;
    return true;
}

static bool device_instance_object_id(VkDevice device, uint64_t *out_instance_object_id) {
    PdockerVkDevice *pdocker_device = NULL;
    if (out_instance_object_id) *out_instance_object_id = 0;
    if (device == VK_NULL_HANDLE) return true;
    if (!device_handle_resolve(device, &pdocker_device)) return false;
    if (!pdocker_device || pdocker_device->instance_object_id == 0) return false;
    if (out_instance_object_id) *out_instance_object_id = pdocker_device->instance_object_id;
    return true;
}

static bool instance_owner_ids_match_or_unowned(
        uint64_t expected_instance_object_id,
        uint64_t owner_instance_object_id) {
    return owner_instance_object_id == 0 ||
           expected_instance_object_id == owner_instance_object_id;
}

