static PdockerVkSurface *surface_unregister_for_instance(
        VkInstance instance,
        VkSurfaceKHR surface) {
    uint64_t instance_object_id = 0;
    if (!instance_handle_object_id(instance, &instance_object_id)) return NULL;
    PdockerVkSurface *target = surface_handle_target(surface);
    if (!target) return NULL;
    PdockerVkSurface **link = &g_surfaces;
    while (*link) {
        if (*link == target) {
            if (!instance_owner_ids_match_or_unowned(
                    instance_object_id, target->owner_instance_id)) {
                return NULL;
            }
            *link = target->next;
            target->next = NULL;
            return target;
        }
        link = &(*link)->next;
    }
    return NULL;
}

static void surface_unregister_all_for_instance_id(uint64_t instance_object_id) {
    if (instance_object_id == 0) return;
    PdockerVkSurface **link = &g_surfaces;
    while (*link) {
        PdockerVkSurface *surface = *link;
        if (surface->owner_instance_id == instance_object_id) {
            *link = surface->next;
            surface->next = NULL;
            surface_retire(surface);
        } else {
            link = &surface->next;
        }
    }
}

