            pdocker_vk_graphics_dynamic_state_bit(VK_DYNAMIC_STATE_SCISSOR) |
            pdocker_vk_graphics_dynamic_state_bit(VK_DYNAMIC_STATE_SCISSOR_WITH_COUNT);
