    rc = send_vulkan_dispatch_v5_frame_with_fds(socket_fd, frame, cursor, fds, fd_count);
cleanup:
    free(dispatch_indirect_options);
    free(frame);
    free(memory_barrier_entries);
    free(buffer_barrier_entries);
